import 'package:flutter/services.dart' show rootBundle;

import 'star_set.dart';
import 'synthetic_galaxy.dart';

/// Loads the synthetic galaxies (SG-1 / SG-2) from their bundled data files —
/// the same 24-byte-record format as the HYG catalogue, generated by
/// `tool/build_synthetic_galaxies.dart` from `SyntheticGalaxy.build` with the
/// parameters `SyntheticGalaxy.all()` uses (so the ids are bit-identical).
///
/// Kept apart from `synthetic_galaxy.dart` (pure Dart) so build tools can run
/// the generator without pulling in Flutter.
class SyntheticGalaxyCatalog {
  SyntheticGalaxyCatalog._();

  static List<HygStars>? _cache;

  /// The fictional galaxies from their data files, cached. Falls back to
  /// regenerating from parameters ([SyntheticGalaxy.all]) if an asset is
  /// missing — the two paths produce identical ids, so callers cannot tell.
  static Future<List<HygStars>> load() async {
    final cached = _cache;
    if (cached != null) return cached;
    try {
      final out = <HygStars>[
        await _loadOne('sg1'),
        await _loadOne('sg2'),
      ];
      _cache = out;
      return out;
    } catch (_) {
      return SyntheticGalaxy.all(); // asset absent → regenerate
    }
  }

  static Future<HygStars> _loadOne(String file) async {
    final bin = await rootBundle.load('assets/stars/$file.bin');
    final parsed = HygStars.fromBinary(bin.buffer.asByteData());
    final rawNamed =
        await rootBundle.loadString('assets/stars/${file}_named.json');
    // The parsed binary's named map is const-empty; rebuild the record with
    // the parsed sidecar merged in.
    final named = HygStars.namedFromJson(rawNamed);
    return HygStars(
      count: parsed.count,
      starId: parsed.starId,
      xyz: parsed.xyz,
      mag: parsed.mag,
      color: parsed.color,
      named: named,
      indexById: parsed.indexById,
    );
  }
}
